// ── Extract & Normalise Incoming Twilio Payload
// Generate a stable ledger_key for idempotent duplicate detection
const d = items[0].json;
const message_id   = d.MessageSid || d.SmsSid || '';
const from_number  = d.From || d.WaId || '';
const to_number    = d.To || '';
const body         = (d.Body || '').trim();
const sms_status   = d.SmsStatus || d.MessageStatus || '';
const num_media    = parseInt(d.NumMedia || '0', 10);
const account_sid  = d.AccountSid || '';
const profile_name = d.ProfileName || '';
const api_version  = d.ApiVersion || '';
const environment  = $env.ENVIRONMENT || 'sandbox';

// Stable ledger key: SHA256 of (from_number + message_body)
// Enables duplicate detection even if Twilio generates a different SID
const crypto = typeof require !== 'undefined' ? require('crypto') : null;
const rawKey = from_number + '|' + body.toLowerCase().trim();
const ledger_key = crypto
  ? crypto.createHash('sha256').update(rawKey).digest('hex').slice(0, 16)
  : 'key_' + Date.now().toString(36);

return [{
  json: {
    message_id, from_number, to_number, message_body: body,
    sms_status, num_media, account_sid, profile_name, api_version,
    environment, is_status_callback: sms_status.length > 0,
    ledger_key,
    received_at: new Date().toISOString()
  }
}];

// ── Check for Duplicate: ledger_key (primary) + message_id (fallback)
const payload = $node["Extract Payload"].data[0].json;
const msgId = payload.message_id;
const ledKey = payload.ledger_key;
const fromNum = payload.from_number;

// Check by: (1) stable ledger_key, (2) message_id (for Twilio retries)
const duplicateByLedger = items.some(item =>
  item.json.ledger_key === ledKey && item.json.from_number === fromNum
);
const duplicateBySid = items.some(item => item.json.message_id === msgId);
const duplicate = duplicateByLedger || duplicateBySid;

return [{
  json: {
    ...payload,
    is_duplicate: duplicate,
    duplicate_by_ledger: duplicateByLedger,
    duplicate_by_sid: duplicateBySid,
    check_timestamp: new Date().toISOString()
  }
}];

// ── Check for Cancel / Stop / Opt-out / Menu / Help Keywords
const payload = $node["Extract Payload"].data[0].json;
const body = payload.message_body || '';
const lowerBody = body.toLowerCase().trim();

// Expanded keyword sets
const cancelKeywords = [
  'cancel','stop','end','quit','unsubscribe',
  'stop all','opt out','optout','pause',
  'i want to stop','please stop','do not send','no more'
];
const menuKeywords  = [
  'menu','options','back','main menu','restart','start over','help'
];

// Phrase-aware matching: check full phrases before substring matches
const isCancel = cancelKeywords.some(k => lowerBody.includes(k)) ||
                 menuKeywords.some(k => lowerBody.includes(k));

// Find the latest conversation for this sender (active preferred)
// Sort by last_message_at descending so newest row comes first
const senderConvs = items
  .filter(item => item.json.from_number === payload.from_number)
  .sort((a, b) => new Date(b.json.last_message_at || 0) - new Date(a.json.last_message_at || 0));

// Prefer the latest active conversation; fall back to most recent row
const activeConv = senderConvs.find(c => c.json.status === 'active') || null;

// Known sender: has any conversation history
const knownSender = senderConvs.length > 0;

return [{
  json: {
    ...payload,
    is_cancel_request: isCancel,
    existing_conversation: activeConv ? activeConv.json : null,
    conversation_id: activeConv ? activeConv.json.conversation_id : payload.message_id,
    current_state: activeConv ? activeConv.json.state : (knownSender ? 'CONSULTING' : 'NEW'),
    has_existing_conv: !!activeConv,
    known_sender: knownSender
  }
}];

// ── Keyword Scorer v2: Phrase-Weighted Intent Detection
const payload = $node["Extract Payload"].data[0].json;
const body = payload.message_body || '';
const lowerBody = body.toLowerCase().trim();

// ── Phase-weight scoring: phrases score higher than single words
// Each entry: [wordOrPhrase, weight] — phrases get weight 3, words weight 1
const keywords = {
  booking: [
    ['book an appointment', 3], ['schedule a meeting', 3], ['need to book', 3],
    ['i want to book', 3], ['can i book', 3], ['book','appointment',1],
    ['reschedule', 2], ['availability', 2], ['follow up', 2], ['make a booking', 3],
    ['schedule', 1], ['meeting', 1], ['consultation', 1], ['slot', 1],
    ['reserve', 1], ['book now', 2]
  ],
  greeting: [
    ['hello', 1], ['hi', 1], ['hey', 1], ['good morning', 2],
    ['good evening', 2], ['namaste', 2], ['how are you', 2], ['hi there', 2]
  ],
  pricing: [
    ['how much', 2], ['what is the price', 3], ['what are your rates', 3],
    ['price', 1], ['cost', 1], ['rate', 1], ['fee', 1], ['charge', 1],
    ['pricing', 2], ['how much does it cost', 3]
  ],
  service: [
    ['what services', 2], ['what do you offer', 3], ['can you help', 2],
    ['service', 1], ['offer', 1], ['provide', 1], ['do you', 1],
    ['help with', 1], ['tell me about', 2]
  ],
  time: [
    ['today', 1], ['tomorrow', 2], ['next week', 2], ['this week', 2],
    ['available', 1], ['when', 1], ['what time', 2], ['later today', 2]
  ],
  name: [
    ['my name is', 3], ['name is', 3], ['i am', 1], ['call me', 2],
    ['i\'m', 1], ['this is', 1]
  ],
  telugu: [
    ['namaskaram', 3], ['emiti', 2], ['ela unnaru', 3], ['bagunnara', 2],
    ['kavali', 2], ['tondara', 2], ['entandi', 2], ['sarle', 1]
  ],
  info: [
    ['what is', 1], ['tell me', 1], ['about', 1], ['information', 1],
    ['details', 1], ['more info', 2], ['i want to know', 2], ['can you tell', 1]
  ],
  thanks: [
    ['thank you very much', 3], ['thanks a lot', 3],
    ['thank you so much', 3], ['thank you', 2], ['thanks', 2],
    ['ok', 1], ['okay', 1], ['got it', 2], ['sure', 1], ['great', 1]
  ]
};

// Score each category using weighted phrases
const scores = {};
for (const [category, patterns] of Object.entries(keywords)) {
  let total = 0;
  for (const [phrase, weight] of patterns) {
    if (lowerBody.includes(phrase)) {
      total += weight;
    }
  }
  scores[category] = total;
}

// Sort by score descending
const sorted = Object.entries(scores).sort((a, b) => b[1] - a[1]);
const topScore = sorted[0][1];
const secondScore = sorted.length > 1 ? sorted[1][1] : 0;

// ── Determine primary intent
let primaryIntent = 'unknown';
let confidence = 0;

if (topScore > 0) {
  primaryIntent = sorted[0][0];
  confidence = topScore;

  // Special: thanks is only terminal if confidence is high and no other strong intent
  if (primaryIntent === 'thanks' && secondScore >= topScore) {
    primaryIntent = sorted[1][0];
  }
  // Give priority to booking if scores are tied
  if (primaryIntent !== 'booking' && scores.booking > 0 && scores.booking >= topScore - 1) {
    primaryIntent = 'booking';
    confidence = Math.max(confidence, scores.booking);
  }
}

// ── Is this a genuine booking intent? More than just mentioning "book" once
const isBookingIntent = scores.booking >= 2 || (scores.booking > 0 && scores.name > 0);

return [{
  json: {
    ...$json,
    keyword_scores: scores,
    primary_intent: primaryIntent,
    confidence,
    top_intents: sorted.filter(s => s[1] > 0).slice(0, 3),
    is_booking_intent: isBookingIntent
  }
}];

// ── State Machine v2: 4-State Model with Explicit Transition Rules
//
// States:  NEW → CONSULTING → BOOKING → DONE
//          Any → CANCELLED (on cancel/stop)
//
// Transition Rules:
//   NEW:          booking_intent → BOOKING, any_other → CONSULTING
//   CONSULTING:   booking_intent → BOOKING, high_confidence + thanks → DONE, else → stay
//   BOOKING:      thanks + name + high_confidence → DONE, else → stay (requires confirmation)
//   DONE:         stay (terminal)
//
// Drift: when intent is unknown but state changes (prevented, logged)
// Unknown state: safely reset to NEW with a drift log

const currentState = $json.is_cancel_request ? 'CANCELLED' : ($json.current_state || 'NEW');
const intent = $json.primary_intent || 'unknown';
const confidence = $json.confidence || 0;
const isBooking = $json.is_booking_intent || false;
const hasBooking = $json.keyword_scores?.booking > 0;

let nextState = currentState;
let stateNote = '';
let driftDetected = false;

// ── Cancel always wins
if ($json.is_cancel_request) {
  nextState = 'CANCELLED';
  stateNote = 'CANCELLED: User requested cancellation';
} else {
  switch (currentState) {
    case 'NEW':
      if (isBooking) {
        nextState = 'BOOKING';
        stateNote = 'NEW -> BOOKING (booking intent)';
      } else {
        nextState = 'CONSULTING';
        stateNote = 'NEW -> CONSULTING (general inquiry)';
      }
      break;

    case 'CONSULTING':
      if (isBooking) {
        nextState = 'BOOKING';
        stateNote = 'CONSULTING -> BOOKING (user wants to book)';
      } else if (intent === 'thanks' && confidence >= 2) {
        // Only resolve to DONE if thanks is genuine (high confidence)
        nextState = 'DONE';
        stateNote = 'CONSULTING -> DONE (resolved with thanks)';
      } else if (confidence >= 3 && intent !== 'unknown') {
        nextState = 'DONE';
        stateNote = 'CONSULTING -> DONE (high confidence resolved)';
      } else {
        stateNote = 'Stayed in CONSULTING (needs more info)';
      }
      break;

    case 'BOOKING':
      // BOOKING → DONE requires confirmation: thanks + name + confidence >= 2
      const hasConfirmation = (intent === 'thanks' || intent === 'name') && confidence >= 2;
      const hasName = intent === 'name' || $json.keyword_scores?.name > 0;
      if (hasConfirmation || (hasName && hasBooking)) {
        nextState = 'DONE';
        stateNote = 'BOOKING -> DONE (confirmed: name + thanks)';
      } else {
        stateNote = 'Stayed in BOOKING (awaiting confirmation)';
      }
      break;

    case 'DONE':
      stateNote = 'DONE: Already completed (no transition)';
      break;

    default:
      // Unknown/corrupted state — reset to NEW with drift notification
      nextState = 'NEW';
      stateNote = 'DRIFT: ' + currentState + ' -> NEW (unknown state reset)';
      driftDetected = true;
  }
}

// ── Drift detection: prevent state change when intent is unknown
// UNLESS it's a cancel request (explicit user action)
if (!driftDetected && currentState !== nextState && intent === 'unknown' && !$json.is_cancel_request) {
  driftDetected = true;
  stateNote = 'DRIFT: ' + currentState + ' -> ' + nextState + ' (blocked — unknown intent)';
  nextState = currentState;  // Rollback — no transition without clear intent
}

// Determine if booking was just completed
const isBookingComplete = nextState === 'DONE' && currentState === 'BOOKING';

return [{
  json: {
    ...$json,
    previous_state: currentState,
    current_state: nextState,
    state_note: stateNote,
    drift_detected: driftDetected,
    is_booking_complete: isBookingComplete
  }
}];

