// ── Build Reply v2: Context-Aware Response Generator
// Can be invoked from cancel path (no State Machine data) or normal path
const isCancel = !!$json.is_cancel_request;
let state = ($json.current_state || 'NEW').toUpperCase();

// If coming from cancel path, current_state might not be CANCELLED yet
if (isCancel) {
  state = 'CANCELLED';
}

const intent = $json.primary_intent || 'unknown';
let reply = '';

switch (state) {
  case 'NEW':
  case 'CONSULTING':
    if (intent === 'greeting') {
      reply = 'Hello! 👋 Welcome to Alance.\n\nI can help with information about our services, pricing, or booking an appointment. What would you like to know?';
    } else if (intent === 'pricing') {
      reply = 'Great question about pricing! 💰\n\nWe offer competitive rates for our services. Could you let me know which specific service you are interested in so I can give you accurate pricing?';
    } else if (intent === 'service') {
      reply = 'Thanks for your interest! 😊 We offer a range of professional services. Could you tell me a bit more about what you need help with?';
    } else if (intent === 'telugu') {
      reply = 'Namaskaram! 🙏\n\nMemu Alance lo meeku sahayam cheyadaniki siddhamga unnam. Meeru emi kosam vethukutunnaru? (We are happy to help you. What are you looking for?)';
    } else {
      reply = 'Hi there! 👋 Welcome to Alance.\n\nI can help with info about our services, pricing, or booking. Just let me know what you need!';
    }
    break;

  case 'BOOKING':
    reply = 'I would be happy to book an appointment for you! 📅\n\nPlease share your preferred date and time, plus your name, and I will get you scheduled right away.';
    break;

  case 'DONE':
    reply = 'Your appointment is confirmed! ✅\n\nWe will send you a reminder before your scheduled time. If you need anything else, just let us know!';
    break;

  case 'CANCELLED':
    reply = 'No problem at all! ✅\n\nYour request has been cancelled. If you ever need our services again, just send us a message. Have a great day!';
    break;

  default:
    reply = 'Thanks for reaching out to Alance! How can I assist you today?';
    break;
}

return [{ json: { ...$json, current_state: state, is_cancel_request: isCancel, reply_text: reply, reply_timestamp: new Date().toISOString() } }];
